package store.service;

import store.model.Domain;
import java.util.*;

public class StoreService {
    public final Map<String,Domain.Category> categories=new LinkedHashMap<>(); public final Map<String,Domain.Product> products=new LinkedHashMap<>(); public final Map<String,Domain.Customer> customers=new LinkedHashMap<>(); public final Map<String,Domain.Supplier> suppliers=new LinkedHashMap<>(); public final Map<String,Domain.Cart> carts=new LinkedHashMap<>(); public final Map<String,Domain.Order> orders=new LinkedHashMap<>(); public final List<Domain.CashflowEntry> cashflow=new ArrayList<>(); public final List<Domain.ReturnRequest> returns=new ArrayList<>(); public final List<Domain.Restock> restocks=new ArrayList<>();
    public void addCategory(Domain.Category c){categories.put(c.getId(),c);} public void addProduct(Domain.Product p){if(products.containsKey(p.getId()))throw new IllegalArgumentException("Duplicate product");products.put(p.getId(),p);} public Domain.Product product(String id){return req(products,id);} public List<Domain.Product> findByName(String n){return products.values().stream().filter(p->p.getName().toLowerCase().contains(n.toLowerCase())).toList();} public List<Domain.Product> byCategory(String id){return products.values().stream().filter(p->p.getCategory().getId().equals(id)).toList();} public void setActive(String id,boolean a){product(id).setActive(a);} public void increaseStock(String id,int q){product(id).increaseStock(q);} public void decreaseStock(String id,int q){product(id).decreaseStock(q);}
    public void addCustomer(Domain.Customer c){if(customers.containsKey(c.getId()))throw new IllegalArgumentException("Duplicate customer");customers.put(c.getId(),c);} public void addSupplier(Domain.Supplier s){if(suppliers.containsKey(s.getId()))throw new IllegalArgumentException("Duplicate supplier");suppliers.put(s.getId(),s);}
    public Domain.Cart createCart(String id,String customer){Domain.Cart c=new Domain.Cart(id,req(customers,customer));carts.put(id,c);return c;} public void addToCart(String cart,String product,int q){carts.get(cart).add(product(product),q);} public void updateCart(String cart,String product,int q){carts.get(cart).update(product,q);} public void removeFromCart(String cart,String product){carts.get(cart).remove(product);} 
    public Domain.Order createOrder(String id,String cartId){Domain.Cart c=req(carts,cartId);if(c.getItems().isEmpty())throw new IllegalArgumentException("Empty cart");List<Domain.OrderItem> items=new ArrayList<>();for(Domain.CartItem i:c.getItems()){i.getProduct().decreaseStock(i.getQuantity());items.add(new Domain.OrderItem(i.getProduct(),i.getQuantity()));}Domain.Order o=new Domain.Order(id,c.getCustomer(),items);orders.put(id,o);return o;}
    public double applyPromotion(String id,Domain.Promotion p){Domain.Order o=req(orders,id);double d=p.discount(o);o.setPromotionDiscount(d);return d;} public double applyShipping(String id,Domain.ShippingMethod m){Domain.Order o=req(orders,id);double v=m==Domain.ShippingMethod.STANDARD?12:m==Domain.ShippingMethod.EXPRESS?25:0;o.setShipping(v);return v;}
    public void cancel(String id){Domain.Order o=req(orders,id);if(o.getStatus()==Domain.OrderStatus.PAID)throw new IllegalArgumentException("Paid order cannot cancel");if(o.getStatus()==Domain.OrderStatus.CANCELLED)throw new IllegalArgumentException("Already cancelled");for(Domain.OrderItem i:o.getItems())i.getProduct().increaseStock(i.getQuantity());o.setStatus(Domain.OrderStatus.CANCELLED);}
    public void pay(String paymentId,String orderId){Domain.Order o=req(orders,orderId);if(o.getStatus()==Domain.OrderStatus.CANCELLED)throw new IllegalArgumentException("Cancelled order");if(o.getStatus()==Domain.OrderStatus.PAID)throw new IllegalArgumentException("Already paid");o.setStatus(Domain.OrderStatus.PAID);cashflow.add(new Domain.CashflowEntry(Domain.CashflowType.INFLOW,"Payment "+paymentId,paymentAmount(o)));} private double paymentAmount(Domain.Order o){return o.getTotal();}
    public Domain.ReturnRequest createReturn(String id,String orderId){Domain.Order o=req(orders,orderId);if(o.getStatus()!=Domain.OrderStatus.PAID)throw new IllegalArgumentException("Only paid orders");Domain.ReturnRequest r=new Domain.ReturnRequest(id,o);returns.add(r);return r;} public void addReturnItem(String returnId,String productId,int q){Domain.ReturnRequest r=returns.stream().filter(x->x.getId().equals(returnId)).findFirst().orElseThrow();Domain.OrderItem oi=r.getOrder().getItems().stream().filter(x->x.getProduct().getId().equals(productId)).findFirst().orElseThrow();int old=r.getItems().getOrDefault(productId,0);if(old+q>oi.getQuantity())throw new IllegalArgumentException("Return exceeds purchase");r.add(product(productId),q);} public void processReturn(String id){Domain.ReturnRequest r=returns.stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow();if(r.getItems().isEmpty()||r.isProcessed())throw new IllegalArgumentException("Invalid return");for(String p:r.getItems().keySet())increaseStock(p,r.getItems().get(p));r.markProcessed();cashflow.add(new Domain.CashflowEntry(Domain.CashflowType.OUTFLOW,"Refund "+id,r.total()));}
    public Domain.Restock restock(String id,String productId,String supplierId,int q,double cost){Domain.Restock r=new Domain.Restock(id,product(productId),req(suppliers,supplierId),q,cost);increaseStock(productId,q);restocks.add(r);cashflow.add(new Domain.CashflowEntry(Domain.CashflowType.OUTFLOW,"Restock "+id,r.getTotal()));return r;} public void manualOutflow(String d,double a){cashflow.add(new Domain.CashflowEntry(Domain.CashflowType.OUTFLOW,d,a));}
    public Map<String,Integer> stockReport(){Map<String,Integer> m=new LinkedHashMap<>();products.forEach((k,v)->m.put(k,v.getStock()));return m;} public Map<String,Integer> salesReport(){Map<String,Integer> m=new LinkedHashMap<>();orders.values().forEach(o->o.getItems().forEach(i->m.merge(i.getProduct().getId(),i.getQuantity(),Integer::sum)));return m;} public Map<Domain.OrderStatus,Long> orderReport(){Map<Domain.OrderStatus,Long> m=new EnumMap<>(Domain.OrderStatus.class);for(Domain.OrderStatus s:Domain.OrderStatus.values())m.put(s,orders.values().stream().filter(o->o.getStatus()==s).count());return m;} public double inflow(){return cashflow.stream().filter(e->e.getType()==Domain.CashflowType.INFLOW).mapToDouble(Domain.CashflowEntry::getAmount).sum();} public double outflow(){return cashflow.stream().filter(e->e.getType()==Domain.CashflowType.OUTFLOW).mapToDouble(Domain.CashflowEntry::getAmount).sum();}
    private static <T> T req(Map<String,T> m,String k){T v=m.get(k);if(v==null)throw new IllegalArgumentException("Unknown id "+k);return v;}
}
